// Which country a point on Earth is in, answered from the same polygon set the
// coverage map draws (src/assets/data/worldCountries.json, generated by
// scripts/generate-world-countries.mjs).
//
// This exists so a Wikidata filming/story location — which arrives as a name
// and a lat/lon, never a country — can be counted against a country with no
// second network lookup and no data migration: the library's stored locations
// are read as they are. Pure and store-free, tested directly.

// The polygons are 110m Natural Earth, so a coastal city (Santa Monica, a
// Hawaiian island) can land a few grid units out to sea. Within this many
// units (~10km each on the 4000-wide grid, so ~80km) of a country's coastline still counts as that
// country; beyond it the point is genuinely at sea, or nowhere we draw.
export const NEAREST_FALLBACK_UNITS = 8;

// Same formula the generator baked the rings with — keep them together.
export function projectPoint (lon, lat, { width, height }) {
  return {
    x: ((lon + 180) / 360) * width,
    y: ((90 - lat) / 180) * height
  };
}

// Per-world bounding boxes so the hot loop can skip most countries without
// walking their rings. WeakMap: a synthetic test world and the real one each
// get their own, and neither is held alive by this module.
const boxesByWorld = new WeakMap();

function boxesFor (world) {
  let boxes = boxesByWorld.get(world);
  if (boxes) return boxes;

  boxes = (world.countries || []).map((country) => {
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;
    country.rings.forEach((ring) => {
      for (let i = 0; i < ring.length; i += 2) {
        if (ring[i] < minX) minX = ring[i];
        if (ring[i] > maxX) maxX = ring[i];
        if (ring[i + 1] < minY) minY = ring[i + 1];
        if (ring[i + 1] > maxY) maxY = ring[i + 1];
      }
    });
    return { country, minX, minY, maxX, maxY };
  });
  boxesByWorld.set(world, boxes);
  return boxes;
}

// Ray casting over a flattened ring: count the edges a horizontal ray to the
// right crosses; odd means inside.
function ringContains (ring, x, y) {
  let inside = false;
  const n = ring.length;
  for (let i = 0, j = n - 2; i < n; j = i, i += 2) {
    const xi = ring[i];
    const yi = ring[i + 1];
    const xj = ring[j];
    const yj = ring[j + 1];
    const crosses = (yi > y) !== (yj > y) &&
      x < ((xj - xi) * (y - yi)) / (yj - yi) + xi;
    if (crosses) inside = !inside;
  }
  return inside;
}

function nearestVertexDistance (ring, x, y) {
  let best = Infinity;
  for (let i = 0; i < ring.length; i += 2) {
    const dx = ring[i] - x;
    const dy = ring[i + 1] - y;
    const distance = dx * dx + dy * dy;
    if (distance < best) best = distance;
  }
  return Math.sqrt(best);
}

/**
 * The country containing (lat, lon), or the nearest one within
 * NEAREST_FALLBACK_UNITS of its coastline, or null.
 */
// Resolved points, kept for the life of the page. A library of ~1,400 films
// has a few thousand distinct places and the polygon walk costs ~0.2ms each
// unthrottled - 740ms for the Places tab, 3.5s at phone speed, and it was
// paid again on every visit (2026-09-23 speed sweep). Keyed by world object
// then by rounded coordinates, so a place is resolved once per session.
const pointsByWorld = new WeakMap();
const pointKey = (lat, lon) => `${lat.toFixed(4)},${lon.toFixed(4)}`;

function resolvedPoints (world) {
  let points = pointsByWorld.get(world);
  if (!points) {
    points = new Map();
    pointsByWorld.set(world, points);
  }
  return points;
}

export function countryForPoint (lat, lon, world) {
  if (!Number.isFinite(lat) || !Number.isFinite(lon) || !world) return null;
  const points = resolvedPoints(world);
  const key = pointKey(lat, lon);
  if (points.has(key)) return points.get(key);
  const found = countryForPointUncached(lat, lon, world);
  points.set(key, found);
  return found;
}

/** True when this point has already been resolved (used by the warm-up). */
export function isPointResolved (lat, lon, world) {
  return Boolean(world) && Number.isFinite(lat) && Number.isFinite(lon) && resolvedPoints(world).has(pointKey(lat, lon));
}

function countryForPointUncached (lat, lon, world) {
  const { x, y } = projectPoint(lon, lat, world);
  const boxes = boxesFor(world);

  for (const box of boxes) {
    if (x < box.minX || x > box.maxX || y < box.minY || y > box.maxY) continue;
    if (box.country.rings.some((ring) => ringContains(ring, x, y))) {
      return box.country;
    }
  }

  const reach = NEAREST_FALLBACK_UNITS;
  let nearest = null;
  let nearestDistance = reach;
  for (const box of boxes) {
    if (x < box.minX - reach || x > box.maxX + reach || y < box.minY - reach || y > box.maxY + reach) continue;
    box.country.rings.forEach((ring) => {
      const distance = nearestVertexDistance(ring, x, y);
      if (distance <= nearestDistance) {
        nearestDistance = distance;
        nearest = box.country;
      }
    });
  }
  return nearest;
}

export function countryForIso (iso, world) {
  if (!iso || !world) return null;
  const wanted = String(iso).toUpperCase();
  return (world.countries || []).find((country) => country.iso && country.iso.toUpperCase() === wanted) || null;
}

// One SVG path per country, every ring closed. Memoized per country object —
// the map re-renders on every count change and the geometry never does.
const pathCache = new WeakMap();

export function pathFor (country) {
  if (!country) return '';
  const cached = pathCache.get(country);
  if (cached) return cached;

  const path = (country.rings || []).map((ring) => {
    const parts = [];
    for (let i = 0; i < ring.length; i += 2) {
      parts.push(`${i === 0 ? 'M' : 'L'}${ring[i]} ${ring[i + 1]}`);
    }
    return `${parts.join('')}Z`;
  }).join('');

  pathCache.set(country, path);
  return path;
}
